package java.util.function;
public interface LongPredicate { boolean test(long value); default LongPredicate and(final LongPredicate p){java.util.Objects.requireNonNull(p);return new LongPredicate(){public boolean test(long v){return LongPredicate.this.test(v)&&p.test(v);}};} default LongPredicate or(final LongPredicate p){java.util.Objects.requireNonNull(p);return new LongPredicate(){public boolean test(long v){return LongPredicate.this.test(v)||p.test(v);}};} default LongPredicate negate(){return new LongPredicate(){public boolean test(long v){return !LongPredicate.this.test(v);}};} }
